        protected void btnEncrypt_OnClick(object sender, EventArgs e)
        {
            try
            {
                txtResult.Text = ServiceLogic.Utility.Encrypt3DES(suscriptor, txtData.Text, txtHash.Text);
            }
            catch (Exception ex)
            {
                txtResult.Text = ex.Message;
            }
        }

        protected void btnDecrypt_OnClick(object sender, EventArgs e)
        {
            try
            {
                txtResult.Text = ServiceLogic.Utility.Decrypt3DES(suscriptor, txtData.Text, txtHash.Text);
